def countStrings(S: str) -> int:
    n = len(S)
    if n == 2:
        return 1

    char_count = {}
    for char in S:
        char_count[char] = char_count.get(char, 0) + 1

    distinct_chars = len(char_count)
    total_swaps = n * (n - 1) // 2

    if distinct_chars == 1:
        return 1
    elif distinct_chars == 2:
        return 2
    else:
        return total_swaps - (n - 1)

# Example usage:
# print(countStrings("geek"))  # Output: 6
# print(countStrings("ab"))    # Output: 1
